#include <iostream>
#include <vector>
template <typename T>
class Stack {
    std::vector<T> v_;
public:
    void push(const T& x) { v_.push_back(x); }
    void pop() { v_.pop_back(); }
    T top() const { return v_.back(); }
    bool empty() const { return v_.empty(); }
};
int main() {
    Stack<int> s;
    s.push(1); s.push(2); s.push(3);
    std::cout << "top=" << s.top() << " size=3\n";
    s.pop();
    std::cout << "after pop top=" << s.top();
}
